+            var stepIndex = i;
+            var cssClass = GetStepClass(stepIndex);
+            <li class="step-item @cssClass"
+                @onclick="() => OnStepClick(stepIndex)"
+                role="button"
+                aria-current="@(stepIndex == CurrentStep ? "step" : null)">
+                <span class="step-number">
+                    @if (stepIndex < CurrentStep)
+                    {
+                        <span class="checkmark">&#10003;</span>
+                    }
+                    else
+                    {
+                        @(stepIndex + 1)
+                    }
+                </span>
+                <span class="step-name">@StepNames[stepIndex]</span>
+            </li>
+            @if (i < StepNames.Length - 1)
+            {
+                <li class="step-connector @(i < CurrentStep ? "completed" : "")" aria-hidden="true"></li>
+            }
+        }
+    </ol>
+</nav>
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    [Parameter] public int CurrentStep { get; set; }
+    [Parameter] public EventCallback<int> OnStepSelected { get; set; }
+
+    private string GetStepClass(int step)
+    {
+        if (step == CurrentStep) return "active";
+        if (step < CurrentStep) return "completed";
+        return "future";
+    }
+
+    private async Task OnStepClick(int step)
+    {
+        if (step < CurrentStep)
+        {
+            await OnStepSelected.InvokeAsync(step);
+        }
+    }
+}
+

