@namespace sv_3659d0512e054adc9d2413c839b4f402.Components.Pages.Apply

<div class="reference-form">
    <div class="entry-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Entry.Name" @oninput="e => Update(name: e.Value?.ToString())" class="form-control" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Entry.Relationship" @oninput="e => Update(relationship: e.Value?.ToString())" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @oninput="e => Update(email: e.Value?.ToString())" class="form-control" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Entry.Phone" @oninput="e => Update(phone: e.Value?.ToString())" class="form-control" />
        </div>
    </div>
</div>

@code {
    [Parameter] public ReferenceModel Entry { get; set; } = new();
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnChanged { get; set; }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void Update(string? name = null, string? relationship = null, string? email = null, string? phone = null)
    {
        if (name is not null) Entry.Name = name;
        if (relationship is not null) Entry.Relationship = relationship;
        if (email is not null) Entry.Email = email;
        if (phone is not null) Entry.Phone = phone;
        OnChanged.InvokeAsync(Entry);
    }
}

