@namespace sv_3659d0512e054adc9d2413c839b4f402.Components.Pages.Apply

<div class="cover-letter-step">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter"
                  class="form-control cover-letter-textarea"
                  rows="12"
                  maxlength="@MaxLength"
                  @bind="Text"
                  @bind:event="oninput"></textarea>
        <div class="char-count @(Text.Length > MaxLength ? "over-limit" : "")">
            @Text.Length / @MaxLength characters
        </div>
    </div>

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(Text);
    }
}

@namespace sv_3659d0512e054adc9d2413c839b4f402.Components.Pages.Apply

<div class="review-step">
    <h2>Review & Submit</h2>
    <p class="step-description">Please review your application before submitting.</p>

    <section class="review-section">
        <div class="review-section-header">
            <h3>Personal Information</h3>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
        </div>
        <dl class="review-data">
            <dt>Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </section>

    <section class="review-section">
        <div class="review-section-header">
            <h3>Work History</h3>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-work-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <div class="review-dates">
                    @entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </section>

    <section class="review-section">
        <div class="review-section-header">
            <h3>References</h3>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="review-reference">
                <strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email, @r.Phone
            </div>
        }
    </section>

    <section class="review-section">
        <div class="review-section-header">
            <h3>Cover Letter</h3>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        <p class="review-cover-letter">@CoverLetter</p>
    </section>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfoStep.PersonalInfoResult Personal { get; set; } = default!;
    [Parameter] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }
}

@code {
    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

