+    color: white;
+}
+
+.step-item.future .step-number {
+    opacity: 0.5;
+}
+
+.checkmark {
+    font-size: 0.9rem;
+}
+
+.step-name {
+    font-size: 0.7rem;
+    text-align: center;
+    color: #64748b;
+    white-space: nowrap;
+}
+
+.step-item.active .step-name {
+    color: #2563eb;
+    font-weight: 600;
+}
+
+.step-item.future .step-name {
+    opacity: 0.5;
+}
+
+.step-connector {
+    flex: 1;
+    height: 2px;
+    background: #cbd5e1;
