+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #1e293b;
+}
+
