+}
+
+.review-work-entry:last-child {
+    border-bottom: none;
+}
+
+.review-dates {
+    font-size: 0.85rem;
+    color: #64748b;
+    margin-top: 0.25rem;
+}
+
+.review-reference {
+    padding: 0.5rem 0;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    color: #374151;
+    line-height: 1.6;
+}
+
+/* Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 2rem;
+    background: #f0fdf4;
+    border: 1px solid #bbf7d0;
+    border-radius: 0.5rem;
+}
+
+.confirmation-icon {
+    width: 4rem;
+    height: 4rem;
+    border-radius: 50%;
+    background: #16a34a;
+    color: white;
+    font-size: 2rem;
+    display: flex;
+    align-items: center;
