+    margin: 0 auto 1.5rem;
+}
+
+.submission-confirmation h2 {
+    color: #166534;
+    margin-bottom: 0.5rem;
+}
+
+.application-id {
+    margin-top: 1rem;
+    font-size: 1.1rem;
+}
