private void Update(string? company = null, string? title = null, DateTime? startDate = null, DateTime? endDate = null, bool? isCurrent = null, string? description = null)
{
    if (company is not null) Entry.Company = company;
    if (title is not null) Entry.Title = title;
    if (startDate is not null) Entry.StartDate = startDate.Value;
    if (endDate is not null) Entry.EndDate = endDate;
    if (isCurrent is not null)
    {
        Entry.IsCurrent = isCurrent.Value;
        if (isCurrent.Value) Entry.EndDate = null;
    }
    if (description is not null) Entry.Description = description;
    OnChanged.InvokeAsync(Entry);
}

private string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
private string? FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd");

private void OnStartDateChanged(ChangeEventArgs e)
{
    if (DateTime.TryParse(e.Value?.ToString(), out var date))
        Update(startDate: date);
}

private void OnEndDateChanged(ChangeEventArgs e)
{
    if (DateTime.TryParse(e.Value?.ToString(), out var date))
        Update(endDate: date);
}

private void OnCurrentChanged(ChangeEventArgs e)
{
    Update(isCurrent: (bool)(e.Value ?? false));
}

